// Worker entry: OpenNext's handler serves every request; the daily cron keeps Supabase awake (D-015).
// Not type-checked by tsc (tsconfig excludes it): the .open-next files only exist after `opennextjs-cloudflare build`.
// @ts-expect-error: generated by the OpenNext build, bundled by wrangler
import handler from "./.open-next/worker.js";
// @ts-expect-error: generated by the OpenNext build. Holds the public build env, the same values the pages use.
import * as nextEnv from "./.open-next/cloudflare/next-env.mjs";
import { wwwRedirect } from "./lib/canonical-host";
import { keepAlive } from "./lib/keep-alive";

type Env = {
  NEXT_PUBLIC_SUPABASE_URL?: string;
  NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY?: string;
  CF_VERSION_METADATA?: { id: string };
};

const worker = {
  // Every response says which Worker version served it, so a deploy or a rollback can be checked from outside (runbook).
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const canonical = wwwRedirect(request.url);
    if (canonical) return Response.redirect(canonical, 301);
    const res: Response = await handler.fetch(request, env, ctx);
    const version = env.CF_VERSION_METADATA?.id;
    if (!version) return res;
    const out = new Response(res.body, res);
    out.headers.set("x-worker-version", version);
    return out;
  },
  // Worker vars win if they're set; otherwise the values baked in at build time.
  async scheduled(_controller: unknown, env: Env) {
    await keepAlive(
      env.NEXT_PUBLIC_SUPABASE_URL ?? nextEnv.production?.NEXT_PUBLIC_SUPABASE_URL,
      env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ?? nextEnv.production?.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    );
  },
};

export default worker;
